 public static Map<String,Object> decode(List<DraftVariable> variables) {Map<String,Object> values=new LinkedHashMap<>();for(DraftVariable v:variables){if(v.getValueText()==null||v.getValueText().trim().isEmpty())continue;values.put(v.getVarKey(),parse(v.getValueText()));}return values;}
