 public static Map<String,Object> plan(List<DraftVariable> variables,Map<String,String> templates) {Map<String,Object> p=plan(decode(variables));p.put("templateKeys",templates==null?Collections.emptySet():templates.keySet());return p;}
 public static Map<String,Object> plan(Map<String,Object> input) {
  Map<String,Object> values=new LinkedHashMap<>();if(input!=null)values.putAll(input);
  if(values.containsKey("targetEdits")&&!values.containsKey("targetOverrides"))values.put("targetOverrides",values.get("targetEdits"));
  Map<String,Object> effective=new LinkedHashMap<>(values);List<Map<String,Object>> unresolved=new ArrayList<>();
  // An adopted threshold wins. Exact duration only supplies an unanswered threshold.
  {Double months=number(values.get("contractPeriodMonths"));Boolean threshold=truth(values.get("periodAtLeast39Months"));if(months!=null&&months>=0){if(threshold==null)effective.put("periodAtLeast39Months",months>=39);else if(threshold!=(months>=39))unresolved.add(issue("input-duration-threshold","InputConflict",null,null,Arrays.asList("contractPeriodMonths","periodAtLeast39Months"),"The adopted 39-month threshold conflicts with the stated duration. The adopted threshold is retained for this draft; review the evidence."));}}
  for(Map<String,Object> f:fields()){
   String key=s(f.get("key"));Boolean applicable=condition(f.get("condition"),effective);
   if(Boolean.FALSE.equals(applicable)){effective.remove(key);continue;}
   String invalid=invalid(key,values.get(key));if(invalid!=null){effective.remove(key);unresolved.add(issue("input-"+key,"InputInvalid",null,null,Collections.singletonList(key),invalid));}
   else if(!Boolean.TRUE.equals(f.get("optional"))&&!answered(effective.get(key)))unresolved.add(issue("input-"+key,applicable==null?"PrerequisiteUnknown":"InputMissing",null,null,Collections.singletonList(key),"Enter or adopt the value for this draft; unknown is not No."));
  }
  if(values.get("contractTitle") instanceof Map){for(String part:Arrays.asList("number","title"))if(!answered(asMap(values.get("contractTitle")).get(part)))unresolved.add(issue("input-contractTitle-"+part,"InputMissing",null,null,Collections.singletonList("contractTitle"),"Complete the missing contract "+part+"; the adopted sibling value is preserved."));}
  String dates=datesIssue(values);if(dates!=null){effective.remove("siteInspectionStartDate");effective.remove("siteInspectionEndDate");unresolved.add(issue("input-siteInspectionDates","InputInvalid","SCT","SCT8",Arrays.asList("siteInspectionStartDate","siteInspectionEndDate"),dates));}
  List<Map<String,Object>> actions=new ArrayList<>();for(Object o:list(RAW.get("actionCatalog"))){Map<String,Object> a=new LinkedHashMap<>(asMap(o));a.put("action","pending");a.put("inputKeys",Collections.emptyList());actions.add(a);}
  Context c=new Context(effective,actions);baseRules(c);additionalRules(c);for(String key:Arrays.asList("advanceRepaymentMonths","advanceRepaymentFirstCertificate"))if(invalid(key,values.get(key))!=null)c.set("scc-advance-repayment-standard","pending",null,"Review the invalid adopted repayment parameter; the original standard wording remains.","请复核无效的采用还款参数；保留原标准条文。",key);adoptTargetEdits(c,values.get("targetOverrides"));references(c);adoptTargetEdits(c,values.get("targetOverrides"));
  for(Object o:list(values.get("targetOverrides"))){Map<String,Object> edit=asMap(o);String id=s(edit.get("actionId"));String problem=DraftTargetDecisions.problem(c.find(id),edit);if(problem!=null)unresolved.add(issue("override-"+id,"InvalidOverride",s(edit.get("document")),s(edit.get("clause")),Collections.singletonList("targetOverrides"),problem));}
  for(Map<String,Object> a:actions)if("pending".equals(a.get("action")))unresolved.add(map("id",a.get("id"),"kind",a.getOrDefault("pendingKind","BusinessValue"),"document",a.get("document"),"clause",a.get("clause"),"inputKeys",a.get("inputKeys"),"message",a.get("detail")));
  return map("ruleVersion",RULE_VERSION,"inputValues",values,"effectiveValues",effective,"derived",c.derived,"actions",actions,"unresolved",unresolved);
 }
 public static Boolean truth(Object v){if(v instanceof Boolean)return(Boolean)v;if(v==null)return null;String t=s(v).trim();if(Arrays.asList("true","Yes","yes","是").contains(t))return true;if(Arrays.asList("false","No","no","否").contains(t))return false;return null;}
 public static boolean answered(Object v){if(v==null)return false;if(v instanceof String)return !s(v).trim().isEmpty()&&!Arrays.asList("unknown","待确定","待確認","To be confirmed").contains(s(v).trim());return true;}
 static Double number(Object v){try{if(!answered(v))return null;double n=Double.parseDouble(s(v));return Double.isFinite(n)?n:null;}catch(RuntimeException ex){return null;}}
 static Boolean and(Boolean... vals){boolean unknown=false;for(Boolean v:vals){if(Boolean.FALSE.equals(v))return false;if(v==null)unknown=true;}return unknown?null:Boolean.TRUE;}
 static String action(Boolean b,String no){return b==null?"pending":b?"retain":no;}
 @SuppressWarnings("unchecked") public static Boolean condition(Object rule,Map<String,Object> values){if(!(rule instanceof Map))return true;Boolean result=true;for(Object o:list(asMap(rule).get("all"))){Map<String,Object> t=asMap(o);Object actual=values.get(s(t.get("field"))), expected=t.get("value");String op=s(t.get("operator"));Boolean term;
  if("unknown".equals(op))term=!answered(actual);
  else if(!answered(actual))term=null;
  else if("eq".equals(op))term=expected instanceof Boolean?Objects.equals(truth(actual),expected):Objects.equals(actual,expected);
  else if("in".equals(op))term=list(expected).contains(actual);
  else if("countGt".equals(op))term=invalid("oldValuableTrees",actual)!=null?null:list(actual).size()>((Number)expected).intValue();
  else if("includesComponent".equals(op)){term=false;for(Object row:list(actual))if(Objects.equals(asMap(row).get("component"),expected))term=true;}
  else term=null;result=and(result,term);
 }return result;}
 static String invalid(String key,Object value){if(!answered(value))return null;
  if(Arrays.asList("advanceRepaymentMonths","advanceRepaymentFirstCertificate").contains(key)){Double n=number(value);if(n==null||n<=0||n!=Math.rint(n))return "A positive integer is required for the repayment period and first certificate number.";}
  if(Arrays.asList("siteInspectionStartDate","siteInspectionEndDate").contains(key)){try{LocalDate.parse(s(value));}catch(RuntimeException ex){return "Use a valid ISO date.";}}
  if(Arrays.asList("photocopyRateUpToA3","photocopyRateAboveA3","contractPeriodMonths","advanceRepaymentMonths","advanceRepaymentFirstCertificate").contains(key)){Double n=number(value);if(n==null||n<0)return "A finite non-negative number is required; the entered value is retained for review.";}
  if("oldValuableTrees".equals(key)){if(!(value instanceof List))return "Tree identities must be a list.";Set<String> seen=new HashSet<>();for(Object o:list(value)){String serial=o instanceof String?s(o):s(asMap(o).get("serial"));if(serial.trim().isEmpty())return "Complete every tree serial number before selecting single or multiple-tree handling.";if(!seen.add(serial.trim().toUpperCase(Locale.ROOT)))return "Duplicate tree serial numbers: verify identities; all entered rows are retained.";}}
  if("billNos".equals(key)){if(!(value instanceof List))return "Bill / Schedule rows must be a list.";Set<String> seen=new HashSet<>();for(Object o:list(value)){Map<String,Object> r=asMap(o);if(!answered(r.get("number"))||!answered(r.get("description")))return "Complete each Bill / Schedule number and exact description.";String identity=s(r.get("type"))+":"+s(r.get("number")).trim().toLowerCase(Locale.ROOT);if(!seen.add(identity))return "Duplicate numbers within the same pricing-document type require review.";}}
  if("sections".equals(key)){if(!(value instanceof List))return "Sections must be a list.";Set<String> seen=new HashSet<>();for(Object o:list(value)){Map<String,Object> r=asMap(o);if(!answered(r.get("designation"))||!answered(r.get("workTypes"))||list(r.get("workTypes")).isEmpty())return "Each Section requires its designation and actual Works types.";if(!seen.add(s(r.get("designation")).trim().toUpperCase(Locale.ROOT)))return "Duplicate Section designations require review.";}}
  return DraftInputRules.structuredIssue(key,value);
 }
